"OLAYLAR_ORTACAG_ORTADOGU:0813-09-24:0":{"b": ["Pada akhir pengepungan Baghdad, Amin dibunuh (malam 24 Muharram 198); Ma'mun naik menjadi khalifah.", "4fc1fe32"], "d": ["Pada akhir pengepungan Baghdad, Amin dibunuh (malam 24 Muharram 198); Ma'mun naik menjadi khalifah.", "4fc1fe32"]},
"OLAYLAR_ORTACAG_ORTADOGU:0815-08-11:0":{"b": ["Ibrahim b. Musa merebut Sana'a (200/815): Yaman keluar dari tangan gubernur Abbasiyah", "49e27fe7"], "d": ["Pemberontak Alawi Ibrahim b. Musa mengalahkan pasukan yang dikirim Ma'mun dan merebut Sana'a (200/815); hingga Hamdawayh b. Mahan mengalahkannya dan memproklamasikan kemerdekaan (203/818), kota keluar dari pemerintahan de facto Khilafah Abbasiyah.", "dc150649"]},
"OLAYLAR_ORTACAG_ORTADOGU:0820-06-17:0":{"b": ["Isa b. Yazid al-Juludi menyingkirkan Hamdawayh (205/820): Sana'a kembali ke pemerintahan gubernur Abbasiyah", "167a2fb1"], "d": ["Hamdawayh b. Mahan, yang telah memproklamasikan kemerdekaan, disingkirkan oleh Isa b. Yazid al-Juludi (205/820); Sana'a dan sekitarnya diperintah oleh gubernur Abbasiyah yang dikirim dari Baghdad hingga tahun 232 (847). Dengan tanggal ini kekosongan Sana'a dalam atlas (815-820) berakhir, masa Khilafah Abbasiyah dimulai.", "72c4a623"]},
"OLAYLAR_ORTACAG_ORTADOGU:0833-08-09:0":{"b": ["Ma'mun wafat dekat Badandun dalam kampanye Bizantium (18 Rajab 218); saudaranya Mu'tasim menjadi khalifah.", "fa3c1a4c"], "d": ["Ma'mun wafat dekat Badandun dalam kampanye Bizantium (18 Rajab 218); saudaranya Mu'tasim menjadi khalifah.", "fa3c1a4c"]},
