"OLAYLAR_ORTACAG_ORTADOGU:0838-01-01:0":{"b": ["Mu'tasim memasuki Anatolia, mengepung dan merebut Ammuriyah (Amorion)", "63534eea"], "d": ["Khalifah Mu'tasim memasuki Anatolia pada 838 dengan pasukan besar; berbaris melalui Ankara, ia mengepung dan merebut Ammuriyah (Amorion), salah satu kota besar Anatolia di dekat Afyon.", "530472b7"]},
"OLAYLAR_ORTACAG_ORTADOGU:0868-09-15:0":{"b": ["Ahmad b. Tulun memasuki Mesir sebagai wakil gubernur; fondasi Tulunid diletakkan", "7bfc6989"], "d": ["Ahmad b. Tulun memasuki Mesir sebagai wakil gubernur; fondasi Tulunid diletakkan", "7bfc6989"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-01-01:0":{"b": ["Pusat pemerintahan dipindahkan ke istana di distrik Qata'i yang baru didirikan (256/870).", "f6fd1a7f"], "d": ["Pusat pemerintahan dipindahkan ke istana di distrik Qata'i yang baru didirikan (256/870).", "f6fd1a7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-08-29:0":{"b": ["Armada Aghlabiyah merebut Malta secara definitif (28 Ramadan 256)", "71f7ca41"], "d": ["Armada di bawah komando Ahmad b. Umar, salah satu komandan Aghlabiyah di Sisilia, merebut Malta secara definitif (28 Ramadan 256 / 29 Agustus 870); pulau itu berada di bawah kekuasaan Bizantium (Romawi Timur) sejak 533, setelah tanggal ini kekuasaan Muslim menjadi permanen. Dalam atlas Malta, Mdina, dan Gozo dicatat sebagai milik Aghlabiyah sejak hari ini.", "a9aa1a35"]},
"OLAYLAR_ORTACAG_ORTADOGU:0884-01-01:0":{"b": ["Ahmad b. Tulun wafat, digantikan putranya Khumarawayh (270/884).", "cad7d779"], "d": ["Ahmad b. Tulun wafat, digantikan putranya Khumarawayh (270/884).", "cad7d779"]},
